2.2 Bivariate Moran’s I


Show code
compute_bivariate_moran &lt;- function(x, y, lw) {
  x[is.na(x)] &lt;- 0
  y[is.na(y)] &lt;- 0
  if (stats::var(x) == 0 || stats::var(y) == 0) return(c(I = NA, p = NA))
  x_std &lt;- as.numeric(scale(x))
  y_std &lt;- as.numeric(scale(y))
  wy    &lt;- spdep::lag.listw(lw, y_std, zero.policy = TRUE)
  I     &lt;- mean(x_std * wy)
  perm_I &lt;- replicate(999, {
    yp  &lt;- y_std[sample(length(y_std))]
    wyp &lt;- spdep::lag.listw(lw, yp, zero.policy = TRUE)
    mean(x_std * wyp)
  })
  p &lt;- mean(abs(perm_I) &gt;= abs(I))
  c(I = I, p = p)
}

