if (!is.null(pdet_munis) && nrow(panel) &gt; 0) {

  # LISA for each J_ variable — build a single long-format sf and facet_wrap
  # (avoids patchwork-over-many-ggplots and keeps HTML small).
  lisa_vars &lt;- intersect(dispute_vars, names(geo_cross))

  cluster_levels &lt;- c("High-High", "Low-Low", "High-Low",
                      "Low-High", "Not significant")
  cluster_colors &lt;- c(
    "High-High"       = "#d7191c",
    "Low-Low"         = "#2c7bb6",
    "High-Low"        = "#fdae61",
    "Low-High"        = "#abd9e9",
    "Not significant" = "#e0e0e0"
  )

  if (length(lisa_vars) &gt; 0) {
    panels &lt;- purrr::map(lisa_vars, function(v) {
      x &lt;- geo_cross[[v]]
      if (sum(!is.na(x)) &lt; 20) return(NULL)
      x[is.na(x)] &lt;- mean(x, na.rm = TRUE)
      if (sd(x, na.rm = TRUE) == 0 || is.na(sd(x, na.rm = TRUE))) return(NULL)

      lm &lt;- tryCatch(
        spdep::localmoran(x, lw, zero.policy = TRUE),
        error = function(e) NULL
      )
      if (is.null(lm)) return(NULL)

      xz &lt;- scale(x)[, 1]
      if (any(!is.finite(xz))) return(NULL)
      lag_xz &lt;- spdep::lag.listw(lw, xz, zero.policy = TRUE)
      p_local &lt;- lm[, "Pr(z != E(Ii))"]

      clean_name &lt;- gsub("^J_", "", gsub("__.*", "", v))
      mi_val &lt;- moran_results$morans_I[moran_results$variable == v]
      panel_label &lt;- sprintf("%s (I=%.3f)", clean_name,
                             if (length(mi_val)) mi_val else NA_real_)

      geo_cross |&gt;
        dplyr::transmute(
          dane_code,
          var_label = panel_label,
          cluster   = factor(dplyr::case_when(
            p_local &gt; 0.05       ~ "Not significant",
            xz &gt; 0 & lag_xz &gt; 0  ~ "High-High",
            xz &lt; 0 & lag_xz &lt; 0  ~ "Low-Low",
            xz &gt; 0 & lag_xz &lt; 0  ~ "High-Low",
            xz &lt; 0 & lag_xz &gt; 0  ~ "Low-High",
            TRUE                  ~ "Not significant"
          ), levels = cluster_levels)
        )
    })

    panels &lt;- purrr::compact(panels)
    if (length(panels) &gt; 0) {
      lisa_sf &lt;- dplyr::bind_rows(panels) |&gt; sf::st_as_sf()
      ncols &lt;- min(3L, length(unique(lisa_sf$var_label)))

      ggplot2::ggplot(lisa_sf) +
        ggplot2::geom_sf(ggplot2::aes(fill = cluster),
                         color = "white", linewidth = 0.15) +
        ggplot2::scale_fill_manual(values = cluster_colors,
                                   name   = "LISA Cluster",
                                   drop   = FALSE) +
        ggplot2::facet_wrap(~var_label, ncol = ncols) +
        ggplot2::theme_void(base_size = 9) +
        ggplot2::theme(
          legend.position = "bottom",
          strip.text      = ggplot2::element_text(size = 7, face = "bold",
                                                  margin = ggplot2::margin(b = 3)),
          plot.margin     = ggplot2::margin(4, 4, 4, 4)
        )
    } else {
      cat("&gt; No J_ variables with sufficient data for LISA.\n")
    }
  }
}













